  ('silk-matte-foundation', 'Silk Matte Foundation', NULL, 'Maison Élan', (select id from categories where slug = 'makeup'), (select id from subcategories where slug = 'foundation' and category_id = (select id from categories where slug = 'makeup')), 'A featherlight, buildable foundation that blurs imperfections and controls shine for a natural matte finish that lasts up to 24 hours without settling into fine lines.', 'Full-coverage, second-skin matte foundation, 24h wear.', '{"Silica Microspheres","Vitamin E","SPF 15"}', '{"Full coverage","24h wear","Oil control"}', '{"bestseller"}', '{}'::jsonb, 1350, NULL, 'EGP', NULL, 20, true, true, false, true, 4.7, 301, '[{"url": "https://picsum.photos/seed/found1/900/1100", "path": null, "position": 0}, {"url": "https://picsum.photos/seed/found1b/900/1100", "path": null, "position": 1}]'::jsonb),
